var t=`0236-souvlaki`;var n=`world-0236`;var a=`GR`;var r=`southern-europe`;var o=4;var s=58;var l={en:`Souvlaki`,ua:`Сувлакі`};var g={en:`A traditional Greece dish made with pork loin, lemon juice, garlic, pita bread. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: свиняча корейка, лимонний сік, часник, піта. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 30 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 30 хвилин.`,t:[`marinating`],m:30,i:[[`pork-loin`,650,`g`],[`extra-virgin-olive-oil`,60,`ml`],[`lemon-juice`,55,`ml`],[`dried-oregano`,5,`g`],[`garlic`,4,`clove`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:10,i:[]},{en:`Grill the skewered pork over medium-high heat, rotating until browned and the thickest pieces reach a safe internal temperature; serve in pita with tzatziki.`,ua:`Готуйте свинину на шпажках над середньо-сильним жаром, повертаючи до рум’яності й безпечної температури всередині; подавайте в піті з дзадзикі.`,t:[`grilling`],m:15,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pita-bread`,300,`g`],[`tzatziki`,180,`g`]]}];var h={slug:t,id:n,country:`GR`,region:r,servings:4,minutes:58,title:l,text:g,steps:d};export{a as country,h as default,n as id,s as minutes,r as region,o as servings,t as slug,d as steps,g as text,l as title};